head.script:
scwin.onwindowchange = function(e) {
    console.log("oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1]);
};
scwin.onclosewindow = function(e) {
    console.log("e.src = " + e.src + ", e,title = " + e.title);
};
scwin.onbeforecloseall = function(e) {
    // false를 리턴하면 close 처리 안됨
    console.log("onbeforecloseall event..");
    return true;
};
scwin.onwindowkeyup = function(e) {
    console.log("onwindowkeyup event..");
    console.log("e.keyCode = " + e.keyCode);
};
scwin.trigger1_onclick = function(e) {
    windowContainer1.createWindow("ddd", "", "windowContainer_processMsgFrame_WESD-612_(WSQ-4699)_sub.xml", "ddd", "ddd", "selectWindow", "", "dddd");
};
scwin.windowContainer1_onwindowload = function(windowId) { //debugger;
};
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    windowContainer1.createWindow("aaa", "", "windowContainer_processMsgFrame_WESD-612_(WSQ-4699)_sub.xml", "abc", "ccccc", "", "", "tooltip");
    //        	windowContainer1.createWindow( "bbb" , "" , "http://www.daum.net" , "def" , "ddddd" , "" , "" , "tooltip" );
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
